// KERNEL: Privileged Network Access Check
#define CAP_NET_RAW 13
#define EPERM -1

struct credentials {
    uid_t euid;
    unsigned long caps;
};

int check_net_privilege(struct credentials *c) {
    if (c->euid == 0) {
        return 0; // Root bypasses checks
    }

    // Must possess required capability
    if (!(c->caps & (1UL << CAP_NET_RAW))) {
        // Context switch returns EPERM
        return EPERM; 
    }

    // Kernel proceeds with interface access
    return 0;
}

